import { describe, expect, it } from 'vitest';
import { ToolError } from '../../core/errors';
import { defaultOptions } from '../../core/registry';
import { resultToText } from '../../core/result-text';
import type { ToolResult } from '../../core/types';
import { fromBase64 } from '../../lib/bytes';
import { decodeScriptEncoder, hasScriptEncoder } from './_script-encoder';
import tool from './script-decode';

// Homemade vectors (generated by the reference encoder, not challenge material).
const JS = '#@~^HQAAAA==C^+.D`EsKw\x09NdmMk2Y|+U^KN+)v#plgoAAA==^#~@';
const JS_PLAIN = "alert('FTF{jscript_encode}');";
const VBS = '#@~^FAAAAA==\x09Um.bwDR21tK~J4+sVKJ8QYAAA==^#~@';
const VBS_PLAIN = 'WScript.Echo "hello"';

const run = (text: string): ToolResult =>
  tool.run(text, defaultOptions(tool as never) as never) as ToolResult;

describe('Script Encoder decoding', () => {
  it('decodes a JScript.Encode block, checksum OK', () => {
    const [b] = decodeScriptEncoder(JS);
    expect(b!.script).toBe(JS_PLAIN);
    expect(b!.checksum).toBe('ok');
    expect(b!.truncated).toBe(false);
  });

  it('decodes a VBScript.Encode block', () => {
    const [b] = decodeScriptEncoder(VBS);
    expect(b!.script).toBe(VBS_PLAIN);
    expect(b!.checksum).toBe('ok');
  });

  it('finds a block embedded in surrounding HTML', () => {
    const html = `<html><script>${JS}</script></html>`;
    const blocks = decodeScriptEncoder(html);
    expect(blocks).toHaveLength(1);
    expect(blocks[0]!.script).toBe(JS_PLAIN);
  });

  it('decodes several blocks in one input', () => {
    const blocks = decodeScriptEncoder(`${JS}\n----\n${VBS}`);
    expect(blocks.map((b) => b.script)).toEqual([JS_PLAIN, VBS_PLAIN]);
  });

  it('flags a bad checksum when the body is edited', () => {
    // Swap two body characters so the decode changes but the length/trailer stay put.
    const i = JS.indexOf('==') + 2;
    const edited = JS.slice(0, i) + 'Z' + JS.slice(i + 1);
    const [b] = decodeScriptEncoder(edited);
    expect(b!.checksum).toBe('bad');
  });

  it('reads the header length as encoded-body bytes, so @-escapes do not over-run the trailer', () => {
    // Body carries @-escapes (one '<' and two newlines), so the decoded length (23) is less than
    // the encoded body length (26). Treating the header as a decoded-char count would keep decoding
    // past the body into the checksum and trailer, producing a garbage tail.
    const block = new TextDecoder().decode(
      fromBase64('I0B+XkdnQUFBQT09cjZQY21QQCFQNCpQUEAmUCxvR2BYI0lAJil4UVVBQUE9PV4jfkA='),
    );
    const [b] = decodeScriptEncoder(block);
    expect(b!.script).toBe('if (a < b) {\n  go(x);\n}');
    expect(b!.length).toBe(23);
    expect(b!.checksum).toBe('ok');
    expect(b!.truncated).toBe(false);
  });

  it('decodes best-effort and marks truncation when bytes are missing', () => {
    const cut = JS.slice(0, JS.length - 20); // drop the trailer and several body chars
    const [b] = decodeScriptEncoder(cut);
    expect(b!.truncated).toBe(true);
    expect(JS_PLAIN).toContain(b!.script); // the readable prefix is a prefix of the real script
  });

  it('ignores a stray marker that is not a real block', () => {
    expect(decodeScriptEncoder('look: #@~^ and ^#~@ in prose')).toEqual([]);
  });

  it('detects the format', () => {
    expect(hasScriptEncoder(JS)).toBe(true);
    expect(hasScriptEncoder('plain text')).toBe(false);
    expect(tool.detect!({ text: JS, bytes: new Uint8Array() })).not.toBeNull();
    expect(tool.detect!({ text: 'nope', bytes: new Uint8Array() })).toBeNull();
  });
});

describe('the tool output', () => {
  it('shows the decoded script and offers to open it elsewhere', () => {
    const txt = resultToText(run(JS));
    expect(txt).toContain('FTF{jscript_encode}');
    expect(txt).toMatch(/Open in/i);
    expect(txt).toContain('offline');
  });

  it('errors clearly when there is no block', () => {
    expect(() => run('just some text')).toThrow(ToolError);
  });

  it('detects which tool to decode the result in next', () => {
    // A block whose decoded script is a Base64 blob (base64 of a URL). Generated by the inverse
    // of the decode tables; round-trip + checksum verified. The raw block holds a 0x7f byte, so
    // it is carried here as base64 of its bytes rather than a fragile literal. Routing should
    // then point at the Base64 tool for the decoded result.
    const toBase64 = new TextDecoder().decode(
      fromBase64(
        'I0B+XkpBQUFBQT09Q19JVDFmS1xTeS5XZX84aDhNYEVlK09ZUzJIVkkmOV5bKSd7WEFzQUFBPT1eI35A',
      ),
    );
    const [b] = decodeScriptEncoder(toBase64);
    expect(b!.script).toBe('aHR0cDovL2V4YW1wbGUuY29tL3NlY3JldA==');
    expect(b!.checksum).toBe('ok');
    const txt = resultToText(run(toBase64));
    expect(txt).toMatch(/Open in Base64/i); // points at the Base64 tool, not a static list
  });

  it('runs every example to its expected text', () => {
    for (const ex of tool.examples) {
      const input = typeof ex.input === 'string' ? ex.input : '';
      expect(resultToText(run(input)), ex.label).toContain(ex.expect);
    }
  });
});
